import { LEVELS, LevelData, PlatformRect } from './levels';

export type Phase = 'ready' | 'playing' | 'paused' | 'won' | 'lost';

export interface Enemy {
  id: number;
  x: number;
  y: number;
  w: number;
  h: number;
  minX: number;
  maxX: number;
  speed: number;
  dir: 1 | -1;
  alive: boolean;
  squash: number;
}

export interface Coin {
  id: number;
  x: number;
  y: number;
  taken: boolean;
}

export interface MovingPlatform {
  id: number;
  baseX: number;
  baseY: number;
  x: number;
  y: number;
  w: number;
  h: number;
  axis: 'x' | 'y';
  range: number;
  speed: number;
  phase: number;
  dx: number;
  dy: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  color: string;
  size: number;
}

export interface FloatText {
  x: number;
  y: number;
  text: string;
  life: number;
  color: string;
}

export interface PlayerState {
  x: number;
  y: number;
  w: number;
  h: number;
  vx: number;
  vy: number;
  onGround: boolean;
  facing: 1 | -1;
  coyote: number;
  jumpBuffer: number;
  invuln: number;
  squash: number;
  blink: number;
}

export interface WorldState {
  phase: Phase;
  levelIndex: number;
  player: PlayerState;
  platforms: PlatformRect[];
  movers: MovingPlatform[];
  coins: Coin[];
  enemies: Enemy[];
  particles: Particle[];
  floats: FloatText[];
  score: number;
  coinCount: number;
  lives: number;
  checkpointX: number;
  time: number;
  goalX: number;
  worldWidth: number;
  levelHeight: number;
  flagY: number;
  flagAnim: number;
  levelCleared: boolean;
  cameraX: number;
  viewW: number;
  shake: number;
  actionCount: number;
  message: string;
}

export const VIEW_W = 900;
export const VIEW_H = 560;

export const PHYSICS = {
  gravity: 1900,
  moveSpeed: 250,
  accel: 1800,
  friction: 1500,
  jumpVelocity: -660,
  maxFall: 900,
  coyoteTime: 0.1,
  jumpBufferTime: 0.12,
};

const PLAYER_W = 26;
const PLAYER_H = 36;

export interface InputFrame {
  left: boolean;
  right: boolean;
  jumpPressed: boolean;
  jumpHeld: boolean;
}

let nextId = 1;

function buildLevel(index: number) {
  const data: LevelData = LEVELS[index];
  const platforms = data.platforms.map((p) => ({ ...p }));
  const movers: MovingPlatform[] = data.movers.map((m) => ({
    id: nextId++,
    baseX: m.x,
    baseY: m.y,
    x: m.x,
    y: m.y,
    w: m.w,
    h: m.h,
    axis: m.axis,
    range: m.range,
    speed: m.speed,
    phase: Math.random() * Math.PI * 2,
    dx: 0,
    dy: 0,
  }));
  const coins = data.coins.map((c) => ({ id: nextId++, x: c.x, y: c.y, taken: false }));
  const enemies = data.enemies.map((e) => ({
    id: nextId++,
    x: e.x,
    y: e.y,
    w: 30,
    h: 26,
    minX: e.minX,
    maxX: e.maxX,
    speed: e.speed,
    dir: 1 as 1 | -1,
    alive: true,
    squash: 0,
  }));
  return { platforms, movers, coins, enemies, data };
}

function makePlayer(spawn: { x: number; y: number }): PlayerState {
  return {
    x: spawn.x,
    y: spawn.y,
    w: PLAYER_W,
    h: PLAYER_H,
    vx: 0,
    vy: 0,
    onGround: false,
    facing: 1,
    coyote: 0,
    jumpBuffer: 0,
    invuln: 0,
    squash: 0,
    blink: 0,
  };
}

function initialCamera(spawnX: number, worldWidth: number): number {
  const desired = spawnX - VIEW_W / 2;
  return Math.max(0, Math.min(worldWidth - VIEW_W, desired));
}

export function createInitialState(): WorldState {
  const built = buildLevel(0);
  const player = makePlayer(built.data.spawn);
  player.y = built.data.groundY - player.h;
  player.onGround = true;
  return {
    phase: 'ready',
    levelIndex: 0,
    player,
    platforms: built.platforms,
    movers: built.movers,
    coins: built.coins,
    enemies: built.enemies,
    particles: [],
    floats: [],
    score: 0,
    coinCount: 0,
    lives: 3,
    checkpointX: built.data.spawn.x,
    time: 0,
    goalX: built.data.goalX,
    worldWidth: built.data.worldWidth,
    levelHeight: built.data.height,
    flagY: 0,
    flagAnim: 0,
    levelCleared: false,
    cameraX: initialCamera(built.data.spawn.x, built.data.worldWidth),
    viewW: VIEW_W,
    shake: 0,
    actionCount: 0,
    message: '',
  };
}

export function startGame(): WorldState {
  const fresh = createInitialState();
  fresh.phase = 'playing';
  fresh.actionCount = 0;
  return fresh;
}

export function restartGame(): WorldState {
  return startGame();
}

export function togglePause(state: WorldState): WorldState {
  if (state.phase === 'playing') return { ...state, phase: 'paused' };
  if (state.phase === 'paused') {
    state.player.jumpBuffer = 0;
    return { ...state, phase: 'playing' };
  }
  return state;
}

function aabb(
  a: { x: number; y: number; w: number; h: number },
  b: { x: number; y: number; w: number; h: number },
): boolean {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

function addParticles(state: WorldState, x: number, y: number, count: number, color: string, spread = 90) {
  for (let i = 0; i < count; i++) {
    state.particles.push({
      x,
      y,
      vx: (Math.random() - 0.5) * spread,
      vy: -Math.random() * 120 - 20,
      life: 0.4 + Math.random() * 0.3,
      maxLife: 0.7,
      color,
      size: 2 + Math.random() * 3,
    });
  }
}

function addFloat(state: WorldState, x: number, y: number, text: string, color: string) {
  state.floats.push({ x, y, text, life: 0.9, color });
}

function hurtPlayer(state: WorldState) {
  if (state.player.invuln > 0) return;
  state.lives -= 1;
  state.shake = 0.35;
  state.player.invuln = 1.4;
  state.player.blink = 1.2;
  state.player.vy = -350;
  state.player.vx = state.player.facing * -180;
  addParticles(state, state.player.x + state.player.w / 2, state.player.y + state.player.h / 2, 10, '#ff6b6b');
  if (state.lives <= 0) {
    state.lives = 0;
    state.phase = 'lost';
  }
}

function fallDeath(state: WorldState) {
  state.lives -= 1;
  state.shake = 0.4;
  if (state.lives <= 0) {
    state.lives = 0;
    state.phase = 'lost';
    return;
  }
  const data = LEVELS[state.levelIndex];
  state.player.x = state.checkpointX;
  state.player.y = data.spawn.y;
  state.player.vx = 0;
  state.player.vy = 0;
  state.player.invuln = 1.4;
  state.player.blink = 1.2;
  state.cameraX = initialCamera(state.checkpointX, state.worldWidth);
}

function loadLevel(state: WorldState, index: number) {
  const built = buildLevel(index);
  state.levelIndex = index;
  state.platforms = built.platforms;
  state.movers = built.movers;
  state.coins = built.coins;
  state.enemies = built.enemies;
  state.player = makePlayer(built.data.spawn);
  state.player.y = built.data.groundY - state.player.h;
  state.player.onGround = true;
  state.player.invuln = 0.6;
  state.checkpointX = built.data.spawn.x;
  state.goalX = built.data.goalX;
  state.worldWidth = built.data.worldWidth;
  state.levelHeight = built.data.height;
  state.flagY = 0;
  state.flagAnim = 0;
  state.levelCleared = false;
  state.cameraX = initialCamera(built.data.spawn.x, built.data.worldWidth);
  state.message = `第 ${index + 1} 关 · ${built.data.name}`;
}

function updateMovers(state: WorldState, dt: number) {
  for (const m of state.movers) {
    m.phase += dt * m.speed;
    const prevX = m.x;
    const prevY = m.y;
    const offset = Math.sin(m.phase) * m.range;
    if (m.axis === 'x') {
      m.x = m.baseX + offset;
      m.y = m.baseY;
    } else {
      m.x = m.baseX;
      m.y = m.baseY + offset;
    }
    m.dx = m.x - prevX;
    m.dy = m.y - prevY;
  }
}

function updatePlayerMovement(state: WorldState, input: InputFrame, dt: number) {
  const p = state.player;
  if (input.jumpPressed) p.jumpBuffer = PHYSICS.jumpBufferTime;
  else p.jumpBuffer = Math.max(0, p.jumpBuffer - dt);
  p.coyote = p.onGround ? PHYSICS.coyoteTime : Math.max(0, p.coyote - dt);

  const dir = (input.right ? 1 : 0) - (input.left ? 1 : 0);
  if (dir !== 0) {
    p.facing = dir as 1 | -1;
    p.vx += dir * PHYSICS.accel * dt;
    if (p.vx > PHYSICS.moveSpeed) p.vx = PHYSICS.moveSpeed;
    if (p.vx < -PHYSICS.moveSpeed) p.vx = -PHYSICS.moveSpeed;
  } else {
    const f = PHYSICS.friction * dt;
    if (Math.abs(p.vx) <= f) p.vx = 0;
    else p.vx -= Math.sign(p.vx) * f;
  }

  if (p.jumpBuffer > 0 && (p.coyote > 0 || p.onGround)) {
    p.vy = PHYSICS.jumpVelocity;
    p.onGround = false;
    p.jumpBuffer = 0;
    p.coyote = 0;
    p.squash = -0.35;
    addParticles(state, p.x + p.w / 2, p.y + p.h, 6, '#d9b382');
  }

  if (!input.jumpHeld && p.vy < -180) {
    p.vy += 1600 * dt;
  }

  p.vy += PHYSICS.gravity * dt;
  if (p.vy > PHYSICS.maxFall) p.vy = PHYSICS.maxFall;

  p.squash += (0 - p.squash) * Math.min(1, dt * 12);
}

function resolveCollisions(state: WorldState, dt: number) {
  const p = state.player;
  const wasOnGround = p.onGround;
  p.onGround = false;

  // 跟随移动平台的水平速度
  for (const m of state.movers) {
    const feetY = p.y + p.h;
    if (
      feetY >= m.y - 2 &&
      feetY <= m.y + m.h + 6 &&
      p.x + p.w > m.x &&
      p.x < m.x + m.w &&
      p.vy >= 0
    ) {
      p.x += m.dx;
    }
  }

  p.x += p.vx * dt;
  for (const plat of state.platforms) {
    if (aabb(p, plat)) {
      if (p.vx > 0) p.x = plat.x - p.w;
      else if (p.vx < 0) p.x = plat.x + plat.w;
      p.vx = 0;
    }
  }
  for (const m of state.movers) {
    if (aabb(p, m)) {
      if (p.vx > 0) p.x = m.x - p.w;
      else if (p.vx < 0) p.x = m.x + m.w;
      p.vx = 0;
    }
  }

  p.y += p.vy * dt;
  for (const plat of state.platforms) {
    if (aabb(p, plat)) {
      if (p.vy > 0) {
        p.y = plat.y - p.h;
        p.vy = 0;
        p.onGround = true;
      } else if (p.vy < 0) {
        p.y = plat.y + plat.h;
        p.vy = 0;
      }
    }
  }
  for (const m of state.movers) {
    if (aabb(p, m)) {
      if (p.vy > 0) {
        p.y = m.y - p.h;
        p.vy = 0;
        p.onGround = true;
        p.x += m.dx;
      } else if (p.vy < 0) {
        p.y = m.y + m.h;
        p.vy = 0;
      }
    }
  }

  if (p.x < 0) {
    p.x = 0;
    p.vx = 0;
  }
  if (p.x + p.w > state.worldWidth) {
    p.x = state.worldWidth - p.w;
    p.vx = 0;
  }

  if (!wasOnGround && p.onGround) {
    p.squash = 0.35;
    addParticles(state, p.x + p.w / 2, p.y + p.h, 5, '#c8e6a0');
  }
}

function updateEnemies(state: WorldState, dt: number) {
  for (const e of state.enemies) {
    if (!e.alive) {
      if (e.squash > 0) e.squash = Math.max(0, e.squash - dt);
      continue;
    }
    e.x += e.dir * e.speed * dt;
    if (e.x < e.minX) {
      e.x = e.minX;
      e.dir = 1;
    } else if (e.x + e.w > e.maxX) {
      e.x = e.maxX - e.w;
      e.dir = -1;
    }
  }
}

function checkEnemyCollisions(state: WorldState) {
  const p = state.player;
  for (const e of state.enemies) {
    if (!e.alive) continue;
    if (!aabb(p, e)) continue;
    const feet = p.y + p.h;
    if (p.vy > 0 && feet - e.y < 22 && p.y < e.y) {
      e.alive = false;
      e.squash = 0.5;
      p.vy = PHYSICS.jumpVelocity * 0.6;
      p.squash = -0.3;
      state.score += 200;
      addFloat(state, e.x + e.w / 2, e.y - 10, '+200', '#ffe066');
      addParticles(state, e.x + e.w / 2, e.y + e.h / 2, 8, '#a0704a');
    } else {
      hurtPlayer(state);
    }
  }
}

function updateCoins(state: WorldState) {
  const p = state.player;
  for (const c of state.coins) {
    if (c.taken) continue;
    const coinBox = { x: c.x - 4, y: c.y - 4, w: 32, h: 32 };
    if (aabb(p, coinBox)) {
      c.taken = true;
      state.coinCount += 1;
      state.score += 100;
      addFloat(state, c.x + 12, c.y - 4, '+100', '#ffe066');
      addParticles(state, c.x + 12, c.y + 12, 6, '#ffd700');
    }
  }
}

function updateGoal(state: WorldState, dt: number) {
  const p = state.player;
  if (state.levelCleared) {
    state.flagAnim += dt;
    state.flagY = Math.min(180, state.flagY + 160 * dt);
    if (state.flagAnim > 1.1 && state.levelIndex < LEVELS.length - 1) {
      loadLevel(state, state.levelIndex + 1);
    }
    return;
  }
  if (p.x + p.w > state.goalX && p.y + p.h > 100) {
    state.levelCleared = true;
    state.flagAnim = 0;
    addFloat(state, state.goalX, 200, '过关！', '#ffffff');
    state.score += 300;
    if (state.levelIndex >= LEVELS.length - 1) {
      state.phase = 'won';
    } else {
      state.message = '过关！';
    }
  }
}

function updateEffects(state: WorldState, dt: number) {
  for (const pt of state.particles) {
    pt.x += pt.vx * dt;
    pt.y += pt.vy * dt;
    pt.vy += 420 * dt;
    pt.life -= dt;
  }
  state.particles = state.particles.filter((pt) => pt.life > 0);
  for (const fl of state.floats) {
    fl.y -= 40 * dt;
    fl.life -= dt;
  }
  state.floats = state.floats.filter((fl) => fl.life > 0);
  if (state.player.invuln > 0) state.player.invuln = Math.max(0, state.player.invuln - dt);
  if (state.player.blink > 0) state.player.blink = Math.max(0, state.player.blink - dt);
  if (state.shake > 0) state.shake = Math.max(0, state.shake - dt);
  if (state.message) {
    state.message = state.message === '过关！' ? state.message : '';
  }
}

function updateCamera(state: WorldState, dt: number) {
  const target = Math.max(
    0,
    Math.min(state.worldWidth - VIEW_W, state.player.x + state.player.w / 2 - VIEW_W / 2),
  );
  state.cameraX += (target - state.cameraX) * Math.min(1, dt * 8);
}

export function update(state: WorldState, input: InputFrame, rawDt: number): WorldState {
  if (state.phase !== 'playing') return state;
  const dt = Math.min(0.05, rawDt);

  if (state.levelCleared) {
    updateMovers(state, dt);
    updateGoal(state, dt);
    updateEffects(state, dt);
    updateCamera(state, dt);
    return state;
  }

  state.time += dt;
  updateMovers(state, dt);
  updatePlayerMovement(state, input, dt);
  resolveCollisions(state, dt);
  updateEnemies(state, dt);
  updateCoins(state);
  checkEnemyCollisions(state);
  updateGoal(state, dt);
  updateEffects(state, dt);

  if (state.player.y > state.levelHeight + 40) {
    fallDeath(state);
  }

  updateCamera(state, dt);
  return state;
}

