import React from 'react';
import { WorldState } from '../game/engine';

interface Props {
  state: WorldState;
  levelName: string;
  bestScore: number;
  onStart: () => void;
  onPause: () => void;
  onResume: () => void;
  onRestart: () => void;
}

export default function GameHud({
  state,
  levelName,
  bestScore,
  onStart,
  onPause,
  onResume,
  onRestart,
}: Props) {
  const { phase, score, coinCount, lives, time } = state;
  const totalCoins = state.coins.length;
  return (
    <>
      <div className="hud">
        <div className="hud-left">
          <div className="hud-item coin"><span className="coin-icon" />{coinCount}</div>
          <div className="hud-item hearts">
            {Array.from({ length: Math.max(0, lives) }).map((_, i) => (
              <span key={i} className="heart">♥</span>
            ))}
          </div>
          <div className="hud-item score">{score}</div>
        </div>
        <div className="hud-right">
          <span className="level-name">第 {state.levelIndex + 1}/3 关 · {levelName}</span>
          <span className="time">{Math.floor(time)}s</span>
          {phase === 'playing' && (
            <button className="icon-btn" data-game-pause onClick={onPause}>暂停</button>
          )}
        </div>
      </div>
      {bestScore > 0 && <div className="best">最佳 {bestScore}</div>}

      {phase === 'ready' && (
        <div className="overlay">
          <div className="panel">
            <h1>草原跳跃</h1>
            <p>← → / A D 移动，空格 / ↑ 跳跃（按住更高）</p>
            <p>踩敌人得分，收集金币，抵达旗杆过关。共三关。</p>
            <button className="primary-btn" data-game-start onClick={onStart}>开始冒险</button>
          </div>
        </div>
      )}
      {phase === 'paused' && (
        <div className="overlay">
          <div className="panel">
            <h2>已暂停</h2>
            <p>分数 {score} · 金币 {coinCount}</p>
            <button className="primary-btn" data-game-resume onClick={onResume}>继续</button>
            <button className="secondary-btn" data-game-restart onClick={onRestart}>重新开始</button>
          </div>
        </div>
      )}
      {phase === 'lost' && (
        <div className="overlay">
          <div className="panel lose">
            <h2>冒险失败</h2>
            <p>得分 {score} · 金币 {coinCount} · 用时 {Math.floor(time)}s</p>
            <button className="primary-btn" data-game-restart onClick={onRestart}>重新开始</button>
          </div>
        </div>
      )}
      {phase === 'won' && (
        <div className="overlay">
          <div className="panel win">
            <h2>通关成功！</h2>
            <p>总得分 {score}</p>
            <p>金币 {coinCount} / {totalCoins} 枚 · 用时 {Math.floor(time)}s</p>
            {bestScore > 0 && <p className="small">历史最佳 {bestScore}</p>}
            <button className="primary-btn" data-game-restart onClick={onRestart}>再玩一次</button>
          </div>
        </div>
      )}
    </>
  );
}

