import React, { useEffect, useRef, useState, useCallback } from 'react';
import {
  WorldState,
  createInitialState,
  update,
  startGame,
  togglePause,
  restartGame,
  VIEW_W,
  VIEW_H,
} from './game/engine';
import { LEVELS } from './game/levels';
import GameHud from './components/GameHud';
import './styles.css';

const KEY_BEST = 'grass-jump-best';

type KeyMap = Record<string, boolean>;

function getBest(): number {
  try {
    const raw = window.atoms?.storage?.get?.(KEY_BEST);
    return raw ? Number(raw) || 0 : 0;
  } catch {
    return 0;
  }
}

function setBest(v: number) {
  try {
    window.atoms?.storage?.set?.(KEY_BEST, String(v));
    window.atoms?.storage?.flush?.();
  } catch {
    // ignore storage failures
  }
}

let audioCtx: AudioContext | null = null;
function beep(freq: number, dur = 0.09, type: OscillatorType = 'square', vol = 0.05) {
  try {
    if (!audioCtx) {
      const Ctor = (window as unknown as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext }).AudioContext
        || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!Ctor) return;
      audioCtx = new Ctor();
    }
    const ac = audioCtx;
    if (ac.state === 'suspended') void ac.resume();
    const osc = ac.createOscillator();
    const gain = ac.createGain();
    osc.type = type;
    osc.frequency.value = freq;
    gain.gain.value = vol;
    gain.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime + dur);
    osc.connect(gain).connect(ac.destination);
    osc.start();
    osc.stop(ac.currentTime + dur);
  } catch {
    // ignore audio failures
  }
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const stateRef = useRef<WorldState>(createInitialState());
  const keysRef = useRef<KeyMap>({});
  const jumpQueuedRef = useRef(false);
  const rafRef = useRef<number>(0);
  const lastRef = useRef<number>(0);
  const lastPhaseRef = useRef<string>('ready');
  const lastCoinRef = useRef(0);
  const lastLivesRef = useRef(3);
  const wonHandledRef = useRef(false);
  const [tick, setTick] = useState(0);
  const [bestScore, setBestScoreState] = useState(0);

  useEffect(() => {
    setBestScoreState(getBest());
  }, []);

  const consumeInput = useCallback(() => {
    const k = keysRef.current;
    const jumpPressed = jumpQueuedRef.current;
    jumpQueuedRef.current = false;
    return {
      left: !!(k['arrowleft'] || k['a']),
      right: !!(k['arrowright'] || k['d']),
      jumpPressed,
      jumpHeld: !!(k['arrowup'] || k[' '] || k['w']),
    };
  }, []);

  const draw = useCallback((state: WorldState) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const cw = canvas.width;
    const ch = canvas.height;
    const scale = Math.min(cw / VIEW_W, ch / VIEW_H);
    const offX = (cw - VIEW_W * scale) / 2;
    const offY = (ch - VIEW_H * scale) / 2;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.fillStyle = '#3a5a7a';
    ctx.fillRect(0, 0, cw, ch);
    ctx.setTransform(scale, 0, 0, scale, offX, offY);

    const sky = ctx.createLinearGradient(0, 0, 0, VIEW_H);
    sky.addColorStop(0, '#6ec6ff');
    sky.addColorStop(0.6, '#a9dcff');
    sky.addColorStop(1, '#dff3ff');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, VIEW_W, VIEW_H);

    const t = performance.now() / 1000;
    const drawCloud = (cx: number, cy: number, sc: number) => {
      ctx.save();
      ctx.globalAlpha = 0.9;
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(cx, cy, 22 * sc, 0, Math.PI * 2);
      ctx.arc(cx + 24 * sc, cy - 8 * sc, 26 * sc, 0, Math.PI * 2);
      ctx.arc(cx + 52 * sc, cy, 20 * sc, 0, Math.PI * 2);
      ctx.arc(cx + 26 * sc, cy + 10 * sc, 22 * sc, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    };
    const camParallax = state.cameraX * 0.3;
    drawCloud(((120 - camParallax * 0.6) % 1200 + 1200) % 1200 - 200, 80, 1);
    drawCloud(((480 - camParallax * 0.5) % 1300 + 1300) % 1300 - 200, 140, 1.2);
    drawCloud(((920 - camParallax * 0.7) % 1400 + 1400) % 1400 - 200, 60, 0.8);

    ctx.fillStyle = '#8fd17a';
    ctx.beginPath();
    ctx.moveTo(0, 460);
    for (let i = 0; i <= VIEW_W; i += 40) {
      const wx = i + state.cameraX * 0.5;
      ctx.lineTo(i, 380 + Math.sin(wx * 0.01) * 40);
    }
    ctx.lineTo(VIEW_W, VIEW_H);
    ctx.lineTo(0, VIEW_H);
    ctx.closePath();
    ctx.fill();

    ctx.save();
    const shake = state.shake > 0 ? (Math.random() - 0.5) * state.shake * 18 : 0;
    ctx.translate(-state.cameraX + shake, shake * 0.5);

    for (const p of state.platforms) {
      ctx.fillStyle = '#9c5a2c';
      ctx.fillRect(p.x, p.y + 10, p.w, p.h - 10);
      ctx.fillStyle = '#5ec14a';
      ctx.fillRect(p.x, p.y, p.w, 10);
      ctx.strokeStyle = 'rgba(0,0,0,0.12)';
      ctx.lineWidth = 1;
      for (let bx = p.x + 16; bx < p.x + p.w; bx += 24) {
        ctx.beginPath();
        ctx.moveTo(bx, p.y + 12);
        ctx.lineTo(bx, p.y + p.h - 4);
        ctx.stroke();
      }
      for (let by = p.y + 22; by < p.y + p.h; by += 16) {
        ctx.beginPath();
        ctx.moveTo(p.x + 2, by);
        ctx.lineTo(p.x + p.w - 2, by);
        ctx.stroke();
      }
      ctx.fillStyle = '#7fe05a';
      for (let gx = p.x + 4; gx < p.x + p.w - 4; gx += 14) {
        ctx.beginPath();
        ctx.moveTo(gx, p.y);
        ctx.lineTo(gx + 3, p.y - 6);
        ctx.lineTo(gx + 7, p.y);
        ctx.closePath();
        ctx.fill();
      }
    }

    // 移动平台
    for (const m of state.movers) {
      ctx.fillStyle = '#a0663a';
      ctx.fillRect(m.x, m.y, m.w, m.h);
      ctx.fillStyle = '#6fdc4f';
      ctx.fillRect(m.x, m.y, m.w, 5);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fillRect(m.x + 4, m.y + m.h - 4, m.w - 8, 2);
    }

    const coinSpin = (Math.sin(t * 6) + 1) / 2;
    for (const c of state.coins) {
      if (c.taken) continue;
      const w = 6 + Math.abs(Math.cos(t * 5 + c.id)) * 12;
      ctx.fillStyle = '#ffd700';
      ctx.beginPath();
      ctx.ellipse(c.x + 12, c.y + 12, Math.max(2, w / 2), 12, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#fff3a0';
      ctx.beginPath();
      ctx.ellipse(c.x + 10, c.y + 8, Math.max(1, w / 4), 5, 0, 0, Math.PI * 2);
      ctx.fill();
      if (coinSpin > 0.8) {
        ctx.fillStyle = 'rgba(255,255,255,0.9)';
        ctx.fillRect(c.x + 8, c.y + 2, 2, 8);
        ctx.fillRect(c.x + 5, c.y + 5, 8, 2);
      }
    }

    for (const e of state.enemies) {
      if (e.alive) {
        const bob = Math.sin(t * 8 + e.id) * 2;
        ctx.fillStyle = '#8b5a2b';
        ctx.beginPath();
        ctx.ellipse(e.x + e.w / 2, e.y + e.h / 2 + bob, e.w / 2, e.h / 2 - 2, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(e.x + e.w / 2 - 5 + e.dir * 2, e.y + 10 + bob, 4, 0, Math.PI * 2);
        ctx.arc(e.x + e.w / 2 + 5 + e.dir * 2, e.y + 10 + bob, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#111111';
        ctx.beginPath();
        ctx.arc(e.x + e.w / 2 - 4 + e.dir * 2, e.y + 10 + bob, 2, 0, Math.PI * 2);
        ctx.arc(e.x + e.w / 2 + 6 + e.dir * 2, e.y + 10 + bob, 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#5c3a1a';
        ctx.fillRect(e.x + 2, e.y + e.h - 4 + bob, 8, 5);
        ctx.fillRect(e.x + e.w - 10, e.y + e.h - 4 + bob, 8, 5);
      } else if (e.squash > 0) {
        ctx.fillStyle = 'rgba(139,90,43,' + Math.min(1, e.squash * 2) + ')';
        ctx.beginPath();
        ctx.ellipse(e.x + e.w / 2, e.y + e.h - 4, e.w / 2, 4, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    const flagX = state.goalX;
    ctx.fillStyle = '#e0e0e0';
    ctx.fillRect(flagX, 120, 6, 320);
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(flagX + 3, 120, 8, 0, Math.PI * 2);
    ctx.fill();
    const flagTop = 130 + state.flagY;
    ctx.fillStyle = state.levelCleared ? '#ffd700' : '#ff4d4d';
    const wave = Math.sin(t * 4) * 6;
    ctx.beginPath();
    ctx.moveTo(flagX + 6, flagTop);
    ctx.lineTo(flagX + 60 + wave, flagTop + 12);
    ctx.lineTo(flagX + 60 + wave, flagTop + 36);
    ctx.lineTo(flagX + 6, flagTop + 46);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.8)';
    ctx.beginPath();
    ctx.arc(flagX + 28, flagTop + 20, 6, 0, Math.PI * 2);
    ctx.fill();

    const p = state.player;
    const blink = p.blink > 0 && Math.floor(t * 20) % 2 === 0;
    ctx.save();
    const sq = p.squash;
    const baseX = p.x + p.w / 2;
    const baseY = p.y + p.h;
    ctx.translate(baseX, baseY);
    ctx.scale(1 - sq * 0.3, 1 + sq * 0.3);
    ctx.globalAlpha = p.invuln > 0 && blink ? 0.45 : 1;
    ctx.fillStyle = blink ? '#ff9f9f' : '#e63946';
    ctx.fillRect(-p.w / 2, -p.h, p.w, 10);
    ctx.fillRect(-p.w / 2 + 2, -p.h - 4, p.w - 6, 6);
    ctx.fillStyle = blink ? '#ffe0e0' : '#ffd9b3';
    ctx.fillRect(-p.w / 2 + 3, -p.h + 10, p.w - 6, 10);
    ctx.fillStyle = '#222222';
    const ed = p.facing === 1 ? 3 : -3;
    ctx.fillRect(-p.w / 2 + 8 + ed, -p.h + 13, 3, 4);
    ctx.fillRect(-p.w / 2 + 16 + ed, -p.h + 13, 3, 4);
    ctx.fillStyle = '#1d63d3';
    ctx.fillRect(-p.w / 2, -p.h + 20, p.w, 16);
    ctx.fillStyle = '#ffd9b3';
    ctx.fillRect(-p.w / 2 + 5, -p.h + 20, 4, 10);
    ctx.fillRect(p.w / 2 - 9, -p.h + 20, 4, 10);
    const armSwing = Math.sin(t * 10) * 2;
    if (!p.onGround) {
      ctx.fillRect(p.facing === 1 ? p.w / 2 - 2 : -p.w / 2 - 4, -p.h + 18, 6, 8);
    } else {
      ctx.fillRect(p.facing === 1 ? p.w / 2 - 2 : -p.w / 2 - 4, -p.h + 22 + armSwing, 6, 8);
    }
    ctx.fillStyle = '#1d63d3';
    if (!p.onGround) {
      ctx.fillRect(-p.w / 2 + 2, -8, 9, 8);
      ctx.fillRect(p.w / 2 - 11, -8, 9, 8);
    } else if (Math.abs(p.vx) > 10) {
      const leg = Math.sin(t * 16) * 3;
      ctx.fillRect(-p.w / 2 + 2, -8 + leg, 9, 8);
      ctx.fillRect(p.w / 2 - 11, -8 - leg, 9, 8);
    } else {
      ctx.fillRect(-p.w / 2 + 2, -8, 9, 8);
      ctx.fillRect(p.w / 2 - 11, -8, 9, 8);
    }
    ctx.restore();

    for (const pt of state.particles) {
      ctx.globalAlpha = Math.max(0, pt.life / pt.maxLife);
      ctx.fillStyle = pt.color;
      ctx.fillRect(pt.x, pt.y, pt.size, pt.size);
    }
    ctx.globalAlpha = 1;

    for (const fl of state.floats) {
      ctx.globalAlpha = Math.min(1, fl.life * 2);
      ctx.fillStyle = fl.color;
      ctx.font = 'bold 18px sans-serif';
      ctx.textAlign = 'center';
      ctx.strokeStyle = 'rgba(0,0,0,0.45)';
      ctx.lineWidth = 3;
      ctx.strokeText(fl.text, fl.x, fl.y);
      ctx.fillText(fl.text, fl.x, fl.y);
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';

    ctx.restore();

    if (state.message) {
      ctx.fillStyle = 'rgba(255,255,255,0.9)';
      ctx.font = 'bold 40px sans-serif';
      ctx.textAlign = 'center';
      ctx.strokeStyle = 'rgba(0,0,0,0.35)';
      ctx.lineWidth = 6;
      ctx.strokeText(state.message, VIEW_W / 2, 120);
      ctx.fillText(state.message, VIEW_W / 2, 120);
      ctx.textAlign = 'left';
    }
  }, []);

  useEffect(() => {
    let disposed = false;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const resize = () => {
      const wrap = canvas.parentElement;
      if (!wrap) return;
      const w = wrap.clientWidth;
      const h = wrap.clientHeight;
      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.max(1, Math.floor(w * dpr));
      canvas.height = Math.max(1, Math.floor(h * dpr));
      canvas.style.width = '100%';
      canvas.style.height = '100%';
    };
    resize();
    window.addEventListener('resize', resize);

    const writeRootAttrs = () => {
      const root = rootRef.current;
      if (!root) return;
      const st = stateRef.current;
      root.setAttribute('data-game-phase', st.phase);
      root.setAttribute('data-game-actions', String(st.actionCount));
      // 玩家屏幕坐标相对于镜头：角色投影在视口中的位置（0..1）。
      // 镜头在开始时和两侧都有活动空间，因此左右移动会让此值变化。
      const screenX = (st.player.x + st.player.w / 2 - st.cameraX) / VIEW_W;
      root.setAttribute('data-playtest-screen-x', screenX.toFixed(4));
      root.setAttribute('data-playtest-player-y', (st.player.y / VIEW_H).toFixed(4));
      root.setAttribute('data-playtest-coins', String(st.coinCount));
    };

    const loop = (now: number) => {
      if (disposed) return;
      const state = stateRef.current;
      if (state.phase === 'playing') {
        const raw = (now - lastRef.current) / 1000;
        lastRef.current = now;
        const dt = Math.min(0.05, Math.max(0, raw));
        const input = consumeInput();
        if (input.left || input.right || input.jumpPressed) {
          state.actionCount += 1;
        }
        const prevCoins = state.coinCount;
        const prevLives = state.lives;
        update(state, input, dt);
        if (state.coinCount > prevCoins) beep(880, 0.08, 'square', 0.04);
        if (state.lives < prevLives) beep(180, 0.16, 'sawtooth', 0.05);
      } else {
        lastRef.current = now;
        jumpQueuedRef.current = false;
      }
      draw(stateRef.current);
      writeRootAttrs();
      if (lastPhaseRef.current !== stateRef.current.phase) {
        lastPhaseRef.current = stateRef.current.phase;
        setTick((v) => v + 1);
      }
      if (lastCoinRef.current !== stateRef.current.coinCount) {
        lastCoinRef.current = stateRef.current.coinCount;
        setTick((v) => v + 1);
      }
      if (lastLivesRef.current !== stateRef.current.lives) {
        lastLivesRef.current = stateRef.current.lives;
        setTick((v) => v + 1);
      }
      rafRef.current = requestAnimationFrame(loop);
    };
    lastRef.current = performance.now();
    rafRef.current = requestAnimationFrame(loop);
    return () => {
      disposed = true;
      cancelAnimationFrame(rafRef.current);
      window.removeEventListener('resize', resize);
    };
  }, [draw, consumeInput]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key === ' ' ? ' ' : e.key.toLowerCase();
      const accepted = ['arrowleft', 'arrowright', 'arrowup', 'arrowdown', ' ', 'a', 'd', 'w', 'p'];
      if (accepted.includes(key)) e.preventDefault();
      const st = stateRef.current;
      if (key === 'p') {
        if (st.phase === 'playing' || st.phase === 'paused') {
          stateRef.current = togglePause(st);
          keysRef.current = {};
          jumpQueuedRef.current = false;
          lastRef.current = performance.now();
          setTick((v) => v + 1);
        }
        return;
      }
      const wasDown = keysRef.current[key];
      keysRef.current[key] = true;
      if (st.phase === 'playing') {
        if ((key === ' ' || key === 'arrowup' || key === 'w') && !wasDown) {
          jumpQueuedRef.current = true;
          beep(520, 0.08, 'square', 0.04);
        }
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      const key = e.key === ' ' ? ' ' : e.key.toLowerCase();
      keysRef.current[key] = false;
    };
    const blur = () => {
      keysRef.current = {};
      jumpQueuedRef.current = false;
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('blur', blur);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('blur', blur);
    };
  }, []);

  // 通关保存最佳分数
  useEffect(() => {
    const st = stateRef.current;
    if (st.phase === 'won' && !wonHandledRef.current) {
      wonHandledRef.current = true;
      const best = Math.max(getBest(), st.score);
      setBest(best);
      setBestScoreState(best);
      beep(660, 0.12, 'triangle', 0.06);
      window.setTimeout(() => beep(880, 0.16, 'triangle', 0.06), 140);
    }
    if (st.phase !== 'won') wonHandledRef.current = false;
  }, [tick]);

  const handleStart = useCallback(() => {
    stateRef.current = startGame();
    keysRef.current = {};
    jumpQueuedRef.current = false;
    lastRef.current = performance.now();
    lastPhaseRef.current = 'playing';
    lastCoinRef.current = stateRef.current.coinCount;
    lastLivesRef.current = stateRef.current.lives;
    setTick((v) => v + 1);
  }, []);

  const handlePause = useCallback(() => {
    stateRef.current = togglePause(stateRef.current);
    keysRef.current = {};
    jumpQueuedRef.current = false;
    lastRef.current = performance.now();
    setTick((v) => v + 1);
  }, []);

  const handleResume = useCallback(() => {
    stateRef.current = togglePause(stateRef.current);
    keysRef.current = {};
    jumpQueuedRef.current = false;
    lastRef.current = performance.now();
    setTick((v) => v + 1);
  }, []);

  const handleRestart = useCallback(() => {
    stateRef.current = restartGame();
    keysRef.current = {};
    jumpQueuedRef.current = false;
    lastRef.current = performance.now();
    lastPhaseRef.current = 'playing';
    lastCoinRef.current = stateRef.current.coinCount;
    lastLivesRef.current = stateRef.current.lives;
    setTick((v) => v + 1);
  }, []);

  const press = (key: string, jump = false) => {
    const st = stateRef.current;
    if (st.phase !== 'playing') return;
    if (!keysRef.current[key]) {
      st.actionCount += 1;
    }
    keysRef.current[key] = true;
    if (jump) jumpQueuedRef.current = true;
    window.setTimeout(() => {
      keysRef.current[key] = false;
    }, 150);
  };

  const st = stateRef.current;
  const levelName = LEVELS[st.levelIndex]?.name ?? '';

  return (
    <div
      ref={rootRef}
      className="game-root"
      data-game-phase={st.phase}
      data-game-actions={st.actionCount}
    >
      <div className="stage-wrap">
        <canvas ref={canvasRef} className="stage" />
      </div>
      <GameHud
        state={st}
        levelName={levelName}
        bestScore={bestScore}
        onStart={handleStart}
        onPause={handlePause}
        onResume={handleResume}
        onRestart={handleRestart}
      />
      <div className="touch-controls">
        <button className="tbtn" data-game-input="left" onPointerDown={() => press('arrowleft')}>◀</button>
        <button className="tbtn jump-btn" data-game-input="jump" onPointerDown={() => press(' ', true)}>跳</button>
        <button className="tbtn" data-game-input="right" onPointerDown={() => press('arrowright')}>▶</button>
      </div>
    </div>
  );
}

