* { box-sizing: border-box; }
html, body, #root { margin: 0; padding: 0; height: 100%; }
body {
  font-family: 'Trebuchet MS', 'Segoe UI', sans-serif;
  background: #1d2b3a;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
}
.game-root {
  position: relative;
  width: 100vw;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.stage-wrap {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: stretch;
  justify-content: stretch;
}
.stage {
  display: block;
  width: 100%;
  height: 100%;
  background: #a9dcff;
  touch-action: none;
}
.hud {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  pointer-events: none;
  z-index: 5;
  color: #fff;
  text-shadow: 2px 2px 0 rgba(0,0,0,0.4);
}
.hud-left, .hud-right {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(20, 40, 60, 0.55);
  padding: 6px 14px;
  border-radius: 24px;
  pointer-events: auto;
}
.hud-item {
  font-weight: 800;
  font-size: 20px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.coin-icon {
  display: inline-block;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #fff3a0, #ffd700 60%, #c79a00);
  box-shadow: 0 0 6px rgba(255, 215, 0, 0.6);
}
.heart { color: #ff5b5b; font-size: 22px; }
.hearts { gap: 2px; }
.hud-right .level-name { font-size: 15px; font-weight: 700; }
.hud-right .time { font-size: 14px; opacity: 0.85; }
.icon-btn {
  pointer-events: auto;
  background: #ffd54a;
  border: none;
  border-radius: 14px;
  padding: 6px 14px;
  font-weight: 800;
  color: #5a3a00;
  cursor: pointer;
  font-size: 14px;
}
.icon-btn:active { transform: scale(0.96); }
.best {
  position: absolute;
  bottom: 12px;
  right: 16px;
  color: rgba(255,255,255,0.75);
  font-size: 13px;
  z-index: 5;
  text-shadow: 1px 1px 0 rgba(0,0,0,0.5);
}
.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(10, 20, 30, 0.52);
  z-index: 10;
}
.panel {
  background: linear-gradient(180deg, #fffdf5, #ffe9b8);
  border: 4px solid #7a532a;
  border-radius: 20px;
  padding: 24px 28px;
  text-align: center;
  box-shadow: 0 12px 0 rgba(0,0,0,0.25);
  max-width: 340px;
  color: #3d2a12;
  margin: 0 16px;
  z-index: 11;
}
.panel h1 { font-size: 30px; margin: 0 0 10px; color: #e63946; letter-spacing: 2px; }
.panel h2 { font-size: 24px; margin: 0 0 12px; color: #e63946; }
.panel p { margin: 6px 0; font-size: 14px; line-height: 1.5; }
.panel .small { font-size: 12px; opacity: 0.7; }
.panel.win h2 { color: #f0a500; }
.panel.lose h2 { color: #8b1e1e; }
.primary-btn, .secondary-btn {
  margin-top: 16px;
  display: block;
  width: 100%;
  padding: 12px 20px;
  border-radius: 14px;
  font-size: 16px;
  font-weight: 800;
  cursor: pointer;
  border: none;
}
.primary-btn {
  background: linear-gradient(180deg, #ffd54a, #f0a500);
  color: #5a3a00;
  box-shadow: 0 4px 0 #b57500;
}
.primary-btn:active { transform: translateY(3px); box-shadow: 0 1px 0 #b57500; }
.secondary-btn {
  margin-top: 10px;
  background: #e8dcc0;
  color: #5a3a00;
  box-shadow: 0 3px 0 #b9a67c;
}
.touch-controls {
  position: absolute;
  bottom: 18px;
  left: 0;
  right: 0;
  display: none;
  justify-content: space-between;
  align-items: flex-end;
  padding: 0 18px;
  z-index: 6;
  pointer-events: none;
}
.touch-controls .tbtn {
  pointer-events: auto;
  width: 68px;
  height: 68px;
  border-radius: 50%;
  border: 3px solid rgba(255,255,255,0.6);
  background: rgba(20, 40, 60, 0.55);
  color: #fff;
  font-size: 22px;
  font-weight: 800;
  touch-action: none;
}
.touch-controls .jump-btn {
  background: rgba(230, 57, 70, 0.7);
  border-color: rgba(255, 220, 220, 0.7);
}
.touch-controls .tbtn:active { background: rgba(255,213,74,0.8); color: #5a3a00; }
@media (max-width: 820px), (pointer: coarse) {
  .touch-controls { display: flex; }
  .hud { top: 8px; left: 8px; right: 8px; }
  .hud-left, .hud-right { padding: 4px 10px; gap: 8px; font-size: 14px; }
  .hud-item { font-size: 16px; }
  .heart { font-size: 16px; }
  .hud-right .level-name { font-size: 12px; }
  .hud-right .time { display: none; }
}
